ce Storm & Freeze Damage Appraisal","url":"https://kansasinsuranceappraiser.com/what-we-handle/ice-storm-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Appraisal","url":"https://kansasinsuranceappraiser.com/what-we-handle/water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://kansasinsuranceappraiser.com/what-we-handle/fire-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire & Grass Fire Appraisal","url":"https://kansasinsuranceappraiser.com/what-we-handle/wildfire-grass-fire-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Farm & Ranch Building Appraisal","url":"https://kansasinsuranceappraiser.com/what-we-handle/farm-ranch-building-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Claim Estimate Review","url":"https://kansasinsuranceappraiser.com/what-we-handle/claim-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://kansasinsuranceappraiser.com/what-we-handle/appraisal-umpire-services/"}}]},"description":"Independent insurance appraisal, estimate review and umpire services for disputed hail, wind, fire and water claims across all 105 Kansas counties.","areaServed":[{"@type":"State","name":"Kansas"},{"@type":"City","name":"Wichita"},{"@type":"City","name":"Overland Park"},{"@type":"City","name":"Kansas City"},{"@type":"City","name":"Olathe"},{"@type":"City","name":"Topeka"},{"@type":"City","name":"Lawrence"},{"@type":"City","name":"Manhattan"},{"@type":"City","name":"Salina"},{"@type":"City","name":"Hutchinson"},{"@type":"City","name":"Dodge City"},{"@type":"City","name":"Garden City"},{"@type":"City","name":"Hays"}],"priceRange":"$$","knowsAbout":["Insurance appraisal","Appraisal clause","Hail damage","Tornado damage","Roof payment schedules","Property claim valuation"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://kansasinsuranceappraiser.com/#website","url":"https://kansasinsuranceappraiser.com/","name":"Kansas Insurance Appraiser","publisher":{"@id":"https://kansasinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://kansasinsuranceappraiser.com/kansas-claim-glossary/#webpage","url":"https://kansasinsuranceappraiser.com/kansas-claim-glossary/","name":"Kansas Claim Glossary | 42 Insurance Terms","description":"Searchable Kansas claim glossary: plain-English definitions of ACV, RCV, roof payment schedules, umpire, holdback and more.","inLanguage":"en-US","isPartOf":{"@id":"https://kansasinsuranceappraiser.com/#website"},"about":{"@id":"https://kansasinsuranceappraiser.com/#business"},"publisher":{"@id":"https://kansasinsuranceappraiser.com/#business"},"dateModified":"2026-11-18","primaryImageOfPage":{"@type":"ImageObject","url":"https://kansasinsuranceappraiser.com/assets/img/photos/documents.webp","width":960,"height":640},"breadcrumb":{"@id":"https://kansasinsuranceappraiser.com/kansas-claim-glossary/#breadcrumb"},"mainEntity":{"@id":"https://kansasinsuranceappraiser.com/kansas-claim-glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://kansasinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim glossary","item":"https://kansasinsuranceappraiser.com/kansas-claim-glossary/"}],"@id":"https://kansasinsuranceappraiser.com/kansas-claim-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Kansas property claim glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. The first payment under most replacement cost policies."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while a home is repaired after a covered loss."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either party demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision, signed by two of the three panel members, that sets the amount of loss."},{"@type":"DefinedTerm","name":"Appraiser","description":"A competent, impartial person chosen by each side to value the loss in appraisal."},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy condition that can reduce payment if a building is insured for less than a required percentage of its value."},{"@type":"DefinedTerm","name":"Cosmetic damage exclusion","description":"An endorsement that excludes hail dents or marks that don’t affect a roof’s function, common on metal roofs."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage for the house itself. Percentage deductibles are often based on this limit."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage, such as detached garages, sheds and fences."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property, or contents, coverage."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing coverages, limits, deductibles and endorsements."},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for removing debris from covered damage, often subject to a separate limit."},{"@type":"DefinedTerm","name":"Demand for appraisal","description":"The written notice that invokes the appraisal clause."},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age and condition. Recoverable depreciation can be paid after repairs."},{"@type":"DefinedTerm","name":"Derecho","description":"A long-lived, widespread windstorm with damaging straight-line winds."},{"@type":"DefinedTerm","name":"Drip edge","description":"Metal flashing along roof edges, often required by code and frequently missed in estimates."},{"@type":"DefinedTerm","name":"Endorsement","description":"A form that adds to or changes the terms of a policy."},{"@type":"DefinedTerm","name":"Estimate","description":"A line-item list of repair quantities and prices, usually prepared in estimating software."},{"@type":"DefinedTerm","name":"FAIR Plan","description":"A state residual market for basic property insurance. Kansas has the Kansas FAIR Plan."},{"@type":"DefinedTerm","name":"Functional damage","description":"Damage that affects how a roof or component performs, as opposed to appearance only."},{"@type":"DefinedTerm","name":"Hail strike","description":"An impact mark from hail, counted in test squares to assess roof damage."},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation withheld until repairs are complete."},{"@type":"DefinedTerm","name":"Ice-and-water shield","description":"A self-adhering roof underlayment used at eaves and valleys to resist ice dams."},{"@type":"DefinedTerm","name":"Kansas Insurance Department","description":"The state agency in Topeka that regulates insurers and helps consumers."},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate, such as a roofing square of shingles or a linear foot of gutter."},{"@type":"DefinedTerm","name":"Matching","description":"The issue of whether repaired areas can reasonably match undamaged areas in color, texture or profile."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping or drying."},{"@type":"DefinedTerm","name":"Ordinance or law","description":"Coverage for added costs to meet current building codes during repairs."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charges for overhead and profit, often 10% and 10%."},{"@type":"DefinedTerm","name":"Payment schedule (roof)","description":"An endorsement that pays a percentage of roof replacement cost based on roof age."},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible calculated as a percentage of the dwelling limit, common for wind and hail."},{"@type":"DefinedTerm","name":"Pitch","description":"Roof slope expressed as rise per 12 inches of run, such as 6/12."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, sometimes requested by the insurer."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace with materials of like kind and quality, without depreciation."},{"@type":"DefinedTerm","name":"Roofing square","description":"One hundred square feet of roof surface."},{"@type":"DefinedTerm","name":"Scope","description":"The list of damaged items and the repairs needed."},{"@type":"DefinedTerm","name":"Steep charge","description":"An added labor charge for roofs with steeper pitches, often 7/12 and above."},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy clause that sets a time limit for suing the insurer."},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for items missed or under-priced in the original estimate."},{"@type":"DefinedTerm","name":"Test square","description":"A 10-by-10-foot area on a roof slope used to count hail strikes."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the appraisers can’t agree on."},{"@type":"DefinedTerm","name":"Wind/hail deductible","description":"A separate deductible that applies to wind and hail losses, often a percentage."}],"@id":"https://kansasinsuranceappraiser.com/kansas-claim-glossary/#definedtermset"}]}</script>
</head>
